/* prog35_perfect_numbers.c
 * Re‑implementation of the original binary's observable behaviour.
 *
 * The program expects a single command‑line argument: a decimal integer n.
 * It prints one of the following messages (each terminated by a newline):
 *
 *   NO_INPUT          – no argument supplied
 *   BAD_INPUT         – argument is not a pure decimal integer
 *   OUT_OF_RANGE      – n > 1 000 000
 *
 * For a valid n (any signed 64‑bit integer, but |n| ≤ 1 000 000) it computes
 * the sum of proper divisors of n and reports whether n is perfect,
 * deficient or abundant:
 *
 *   n=%lld sum=%lld perfect
 *   n=%lld sum=%lld deficient
 *   n=%lld sum=%lld abundant
 *
 * The implementation follows the exact logic of the original program,
 * including the handling of zero and negative numbers.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int main(int argc, char **argv) {
    /* 1. Argument presence check */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* 2. Strict integer parsing (base 10) */
    char *endptr = NULL;
    errno = 0;
    long long n = strtoll(argv[1], &endptr, 10);

    /* No digits, overflow/underflow, or leftover characters */
    if (endptr == argv[1] || errno == ERANGE || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* 3. Upper‑range check (original accepts up to 1 000 000) */
    if (n > 1000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* 4. Compute sum of proper divisors */
    long long sum = 0;
    if (n > 0) {
        for (long long d = 1; d * d <= n; ++d) {
            if (n % d == 0) {
                long long other = n / d;
                if (d != n) sum += d;                 // d is a proper divisor
                if (other != d && other != n) sum += other; // paired divisor
            }
        }
    }

    /* 5. Classification output */
    if (sum == n) {
        printf("n=%lld sum=%lld perfect\n", n, sum);
    } else if (sum < n) {
        printf("n=%lld sum=%lld deficient\n", n, sum);
    } else {
        printf("n=%lld sum=%lld abundant\n", n, sum);
    }

    return 0;
}
